using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
namespace OcctSharp.Generator.Tests;
public sealed class FoundationValueContractTests {
 static ClosedWorkflowOperationContract Contract=>ClosedWorkflowOperationContract.FoundationValues;
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,BindingDeclarationKind.Method,op.NativeName.Split("::")[0]+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,ProductModule=OcctProductModule.Foundation};
 [Fact]public void SignatureDriftAndUnsafeAccessCannotEnterCopiedProfile(){foreach(var op in Contract.Operations.Values){var d=Declaration(op);Assert.True(Contract.Contains(d));Assert.False(Contract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(Contract.Contains(d with{Access=BindingAccess.Private}));Assert.False(Contract.Contains(d with{IsDeleted=true}));Assert.False(Contract.Contains(d with{IsTemplated=true}));}}
 [Fact]public void SupportCannotPublishAndPartialClosureFails(){Assert.Empty(ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(Contract.Operations.Values.Where(x=>x.Supporting).Select(Declaration)),Contract).Files);Assert.Throws<InvalidDataException>(()=>ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel([Declaration(Contract.Operations.Values.First(x=>!x.Supporting))]),Contract));}
 [Fact]public void CopiedEmissionIsDeterministicAndContainsActualSafetyGuards(){var rows=Contract.Operations.Values.Select(Declaration).ToArray();var a=ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(rows),Contract);var b=ClosedWorkflowOperationEmitter.Emit("8.0.1",new BindingModel(rows.Reverse()),Contract);Assert.Equal(a.Files.Select(f=>f.Content),b.Files.Select(f=>f.Content));Assert.Equal(3,a.Files.Count);Assert.All(a.Files,f=>Assert.Equal(OcctProductModule.Foundation,f.ProductModule));string native=a.Files.Single(x=>x.RelativePath.EndsWith(".cpp",StringComparison.Ordinal)).Content;Assert.Contains("static_cast<size_t>(n)+1",native);Assert.Contains("Operation would split a surrogate pair",native);Assert.Contains("Incompatible unit dimensions",native);Assert.Contains("std::from_chars",native);Assert.DoesNotContain("UnitsAPI::Check",native);}
 [Fact]public void UnavailableOrGlobalOperationsRemainDeferred(){Assert.DoesNotContain(Contract.Operations.Values,o=>o.NativeName.Contains("SetCurrent")||o.NativeName.Contains("ExpandedName")||o.NativeName.Contains("LocateExecFile")||o.Signature.Contains("std::istream")||o.Signature=="TCollection_AsciiString::IsEqual: bool (const TCollection_AsciiString &, const char *const)");}
}
